namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be in format: XX000000 (2 letters followed by 6 digits)")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS101", DepartmentId = 1, DepartmentName = "Computer Science", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented programming.", Credits = 3, Schedule = "Mon/Wed 9:00-10:30 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Ph.D. in Computer Science from MIT with 15 years of teaching experience.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS201", DepartmentId = 1, DepartmentName = "Computer Science", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Algorithm design and analysis.", Credits = 4, Schedule = "Tue/Thu 11:00 AM-12:30 PM", InstructorName = "Dr. James Park", InstructorBio = "Former software engineer at Google, specializing in algorithm optimization.", IsFeatured = true },
            new() { Id = 3, Title = "Operating Systems", Code = "CS301", DepartmentId = 1, DepartmentName = "Computer Science", Description = "Principles of operating system design including process management, memory management, and file systems.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00-2:00 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Researcher in distributed systems with publications in top-tier conferences.", IsFeatured = false },
            new() { Id = 4, Title = "Calculus I", Code = "MATH101", DepartmentId = 2, DepartmentName = "Mathematics", Description = "Introduction to differential calculus including limits, derivatives, and applications.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00-9:00 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Award-winning educator with a passion for making calculus accessible.", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH201", DepartmentId = 2, DepartmentName = "Mathematics", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues.", Credits = 3, Schedule = "Tue/Thu 2:00-3:30 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Published researcher in applied mathematics and numerical methods.", IsFeatured = false },
            new() { Id = 6, Title = "Discrete Mathematics", Code = "MATH210", DepartmentId = 2, DepartmentName = "Mathematics", Description = "Logic, sets, relations, functions, counting, and graph theory.", Credits = 3, Schedule = "Mon/Wed 3:00-4:30 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Award-winning educator with a passion for making calculus accessible.", IsFeatured = false },
            new() { Id = 7, Title = "General Physics I", Code = "PHYS101", DepartmentId = 3, DepartmentName = "Physics", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Mon/Wed 10:00-11:30 AM + Lab Fri 2:00-5:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Experimental physicist specializing in optics and photonics.", IsFeatured = true },
            new() { Id = 8, Title = "Electromagnetism", Code = "PHYS201", DepartmentId = 3, DepartmentName = "Physics", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 9:00-10:30 AM", InstructorName = "Dr. Lisa Chang", InstructorBio = "Theoretical physicist with research in quantum electrodynamics.", IsFeatured = false },
            new() { Id = 9, Title = "Quantum Mechanics", Code = "PHYS301", DepartmentId = 3, DepartmentName = "Physics", Description = "Introduction to quantum theory, wave functions, and the Schrödinger equation.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00 AM-12:00 PM", InstructorName = "Dr. Lisa Chang", InstructorBio = "Theoretical physicist with research in quantum electrodynamics.", IsFeatured = false },
            new() { Id = 10, Title = "English Composition", Code = "ENG101", DepartmentId = 4, DepartmentName = "English", Description = "Develop academic writing skills including argumentation, research, and critical analysis.", Credits = 3, Schedule = "Tue/Thu 10:00-11:30 AM", InstructorName = "Prof. David Mitchell", InstructorBio = "Published author and writing coach with 20 years in higher education.", IsFeatured = false },
            new() { Id = 11, Title = "American Literature", Code = "ENG201", DepartmentId = 4, DepartmentName = "English", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Mon/Wed 2:00-3:30 PM", InstructorName = "Dr. Karen White", InstructorBio = "Specialist in 20th-century American fiction and cultural studies.", IsFeatured = true },
            new() { Id = 12, Title = "Creative Writing", Code = "ENG210", DepartmentId = 4, DepartmentName = "English", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction.", Credits = 3, Schedule = "Thu 6:00-9:00 PM", InstructorName = "Prof. David Mitchell", InstructorBio = "Published author and writing coach with 20 years in higher education.", IsFeatured = false }
        };
    }

    public Task<List<Department>> GetDepartmentsAsync()
    {
        return Task.FromResult(_departments.ToList());
    }

    public Task<List<Course>> GetCoursesAsync(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return Task.FromResult(query.ToList());
    }

    public Task<Course?> GetCourseByIdAsync(int id)
    {
        return Task.FromResult(_courses.FirstOrDefault(c => c.Id == id));
    }

    public Task<List<Course>> GetFeaturedCoursesAsync()
    {
        return Task.FromResult(_courses.Where(c => c.IsFeatured).ToList());
    }

    public Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return Task.FromResult(true);
    }
}

