@page "/courses"
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="search-bar">
        <input type="text" @bind="searchTerm" @bind:event="oninput" placeholder="Search courses by title, code, or instructor..." class="search-input" />
        <select @bind="selectedDepartmentId" class="filter-select">
            <option value="0">All Departments</option>
            @if (departments != null)
            {
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
        <button class="btn-search" @onclick="SearchCourses">Search</button>
    </div>

    @if (courses == null)
    {
        <p>Loading courses...</p>
    }
    else if (!courses.Any())
    {
        <p class="no-results">No courses found matching your criteria.</p>
    }
    else
    {
        <div class="course-list">
            @foreach (var course in courses)
            {
                <div class="course-list-item">
                    <div class="course-list-info">
                        <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                        <p class="course-meta">@course.Code &bull; @course.DepartmentName &bull; @course.Credits Credits</p>
                        <p>@course.Description</p>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    private List<Course>? courses;
    private List<Department>? departments;
    private string searchTerm = string.Empty;
    private int selectedDepartmentId;

    protected override async Task OnInitializedAsync()
    {
        departments = await CatalogService.GetDepartmentsAsync();
        await SearchCourses();
    }

    private async Task SearchCourses()
    {
        int? deptId = selectedDepartmentId > 0 ? selectedDepartmentId : null;
        courses = await CatalogService.GetCoursesAsync(searchTerm, deptId);
    }
}

@page "/enroll"
@inject CatalogService CatalogService

<PageTitle>Enroll</PageTitle>

<div class="container">
    <h1>Course Enrollment</h1>
    <p class="enroll-subtitle">Fill out the form below to submit your enrollment request.</p>

    @if (submitted)
    {
        <div class="success-message">
            <h2>Enrollment Submitted!</h2>
            <p>Your enrollment request has been successfully submitted. You will receive a confirmation email shortly.</p>
            <a href="/courses" class="btn-back">Browse More Courses</a>
        </div>
    }
    else
    {
        <EditForm Model="@model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
            <DataAnnotationsValidator />
            <ValidationSummary />

            <div class="form-group">
                <label for="studentName">Full Name</label>
                <InputText id="studentName" @bind-Value="model.StudentName" class="form-input" placeholder="Enter your full name" />
                <ValidationMessage For="@(() => model.StudentName)" />
            </div>

            <div class="form-group">
                <label for="studentId">Student ID</label>
                <InputText id="studentId" @bind-Value="model.StudentId" class="form-input" placeholder="e.g. AB123456" />
                <ValidationMessage For="@(() => model.StudentId)" />
            </div>

            <div class="form-group">
                <label for="courseId">Course</label>
                <InputSelect id="courseId" @bind-Value="model.CourseId" class="form-input">
                    <option value="0">-- Select a Course --</option>
                    @if (courses != null)
                    {
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code - @course.Title</option>
                        }
                    }
                </InputSelect>
                <ValidationMessage For="@(() => model.CourseId)" />
            </div>

            <button type="submit" class="btn-submit">Submit Enrollment</button>
        </EditForm>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    private List<Course>? courses;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        courses = await CatalogService.GetCoursesAsync(null, null);
    }

    private async Task HandleSubmit()
    {
        var result = await CatalogService.SubmitEnrollmentRequestAsync(model);
        if (result)
        {
            submitted = true;
        }
    }
}

